ername || user?.username }}</div>\r\n          </div>\r\n        </div>\r\n\r\n        <hr>\r\n\r\n        <!-- Cambio password -->\r\n        <button type=\"button\" class=\"btn btn-link p-0 d-flex align-items-center change-toggle\" (click)=\"toggleChange()\">\r\n          <i class=\"fas me-2\" [ngClass]=\"{'fa-chevron-down': !changeExpanded, 'fa-chevron-up': changeExpanded}\"></i>\r\n          <i class=\"fas fa-key me-2\"></i>Cambia Password\r\n        </button>\r\n\r\n        <div *ngIf=\"changeExpanded\" class=\"change-section mt-2\">\r\n          <form [formGroup]=\"changeForm\" (ngSubmit)=\"onSubmit()\" novalidate>\r\n            <div class=\"mb-3\">\r\n              <label for=\"currentPassword\" class=\"form-label\">Password Attuale</label>\r\n              <input type=\"password\" id=\"currentPassword\" formControlName=\"currentPassword\" class=\"form-control\"\r\n                     [ngClass]=\"{'is-invalid': changeForm.get('currentPassword')?.invalid && changeForm.get('currentPassword')?.touched}\"\r\n                     placeholder=\"Inserisci la password attuale\" autocomplete=\"current-password\">\r\n              <div class=\"invalid-feedback\">Password attuale obbligatoria</div>\r\n            </div>\r\n\r\n            <div class=\"mb-3\">\r\n              <label for=\"newPassword\" class=\"form-label\">Nuova Password</label>\r\n              <input type=\"password\" id=\"newPassword\" formControlName=\"newPassword\" class=\"form-control\"\r\n                     [ngClass]=\"{'is-invalid': changeForm.get('newPassword')?.invalid && changeForm.get('newPassword')?.touched}\"\r\n                     placeholder=\"Inserisci la nuova password\" autocomplete=\"new-password\">\r\n              <div class=\"text-danger small mt-1 password-requirements\">\r\n                La password deve contenere almeno 10 caratteri, di cui numeri, lettere minuscole, lettere maiuscole e caratteri speciali.\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"mb-3\">\r\n              <label for=\"confirmPassword\" class=\"form-label\">Conferma Nuova Password</label>\r\n              <input type=\"password\" id=\"confirmPassword\" formControlName=\"confirmPassword\" class=\"form-control\"\r\n                     [ngClass]=\"{'is-invalid': changeForm.get('confirmPassword')?.invalid && changeForm.get('confirmPassword')?.touched}\"\r\n                     placeholder=\"Ripeti la nuova password\" autocomplete=\"new-password\">\r\n              <div class=\"invalid-feedback\" *ngIf=\"changeForm.get('confirmPassword')?.errors?.['mismatch']\">Le password non coincidono</div>\r\n              <div class=\"invalid-feedback\" *ngIf=\"changeForm.get('confirmPassword')?.errors?.['required']\">Conferma obbligatoria</div>\r\n            </div>\r\n\r\n            <button type=\"submit\" class=\"btn btn-primary\" [disabled]=\"changing\">\r\n              <span *ngIf=\"changing\" class=\"spinner-border spinner-border-sm me-1\"></span>\r\n              Aggiorna Password\r\n            </button>\r\n          </form>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-secondary\" (click)=\"close()\">Chiudi</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Conferma aggiornamento password -->\r\n<div class=\"modal-backdrop fade show confirm-backdrop\" *ngIf=\"showConfirm\" (click)=\"cancelConfirm()\"></div>\r\n<div class=\"modal d-block confirm-modal\" *ngIf=\"showConfirm\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"confirmPasswordLabel\">\r\n  <div class=\"modal-dialog modal-dialog-centered\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header bg-primary text-white\">\r\n        <h5 class=\"modal-title\" id=\"confirmPasswordLabel\"><i class=\"fas fa-key me-2\"></i>Conferma aggiornamento</h5>\r\n      </div>\r\n      <div class=\"modal-body\">\r\n        Sei sicuro di voler aggiornare la password?\r\n      </div>\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-secondary\" (click)=\"cancelConfirm()\">Annulla</button>\r\n        <button type=\"button\" class=\"btn btn-primary\" (click)=\"confirmChange()\">Conferma</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Esito aggiornamento password -->\r\n<div class=\"modal-backdrop fade show result-backdrop\" *ngIf=\"showResultModal\" (click)=\"closeResultModal()\"></div>\r\n<div class=\"modal d-block result-modal\" *ngIf=\"showResultModal\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"resultPasswordLabel\">\r\n  <div class=\"modal-dialog modal-dialog-centered\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header text-white\" [ngClass]=\"{'bg-success': resultSuccess, 'bg-danger': !resultSuccess}\">\r\n        <h5 class=\"modal-title\" id=\"resultPasswordLabel\">\r\n          <i class=\"fas me-2\" [ngClass]=\"{'fa-check-circle': resultSuccess, 'fa-exclamation-triangle': !resultSuccess}\"></i>\r\n          {{ resultSuccess ? 'Password aggiornata' : 'Aggiornamento non riuscito' }}\r\n        </h5>\r\n      </div>\r\n      <div class=\"modal-body\">\r\n        {{ resultMessage }}\r\n      </div>\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn\" [ngClass]=\"{'btn-success': resultSuccess, 'btn-danger': !resultSuccess}\" (click)=\"closeResultModal()\">OK</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>",
      styles: [".user-profile-modal .modal-dialog{margin-top:.75rem;margin-bottom:.75rem}.user-profile-modal .modal-body{max-height:82vh;overflow-y:auto;padding:.75rem 1rem}.user-profile-modal .modal-header,.user-profile-modal .modal-footer{padding:.45rem .9rem}.user-profile-modal .modal-title{font-size:1.05rem}.user-profile-modal .password-requirements{line-height:1.2;font-size:.72rem}.user-profile-modal .form-label.small{text-transform:uppercase;font-size:.62rem;letter-spacing:.03rem;margin-bottom:0}.user-profile-modal .profile-grid{--bs-gutter-y: .35rem;--bs-gutter-x: .75rem}.user-profile-modal .profile-grid .fw-semibold{font-size:.9rem}.user-profile-modal hr{margin:.45rem 0}.user-profile-modal .mb-3{margin-bottom:.6rem!important}.user-profile-modal .form-control{padding:.35rem .6rem;font-size:.9rem}.user-profile-modal .username-cell{background-color:#eef9ee;border:1px solid #b9e3b9;border-radius:.4rem;padding:.25rem .5rem}.user-profile-modal .change-toggle{text-decoration:none;font-size:1rem;font-weight:600;color:#0d6efd}.user-profile-modal .change-toggle:hover{text-decoration:none}.confirm-backdrop{z-index:1060}.confirm-modal{z-index:1065}.result-backdrop{z-index:1070}.result-modal{z-index:1075}\n"]
    }]
  }],
